 /// 📤️ A completed value moves once; every original parsing obligation is already terminal.
 pub fn take(&mut self,cx:&mut StepContext<'_>,output:&mut Option<T>)->Result<bool,OriginalTurnFailure>{self.validate(cx)?;if self.phase!=10||self.closing||self.output.is_none(){return Err(invalid().into())}let d=fixed::<(Option<T>,Option<T>)>();built(cx,output,construction(d),||Ok((self.output.take().ok_or_else(invalid)?,receipt(d))))}
